(function () {
  function registerFor(generatorObj, mode) {
    if (!generatorObj || !generatorObj.forBlock) {
      return;
    }

    var isArduino = mode === 'arduino';
    var emit = function (pythonCall, commentText) {
      if (isArduino) {
        return '// ' + commentText + '\n';
      }
      return pythonCall;
    };

    var getNumberField = function (block, key, fallback) {
      var raw = block && typeof block.getFieldValue === 'function' ? block.getFieldValue(key) : null;
      var n = Number(raw);
      if (!Number.isFinite(n)) {
        return fallback;
      }
      return n;
    };

    generatorObj.forBlock['cf_test_link'] = function () {
      return emit('cf_test_link();\n', 'cf_test_link()');
    };

    generatorObj.forBlock['cf_takeoff'] = function () {
      return emit('cf_takeoff();\n', 'cf_takeoff()');
    };

    generatorObj.forBlock['cf_land'] = function () {
      return emit('cf_land();\n', 'cf_land()');
    };

    generatorObj.forBlock['cf_move_forward'] = function () {
      var dist = getNumberField(this, 'DIST', 0.5);
      return emit("cf_move('forward', " + dist + ");\n", "cf_move('forward', " + dist + ")");
    };

    generatorObj.forBlock['cf_move_back'] = function () {
      var dist = getNumberField(this, 'DIST', 0.5);
      return emit("cf_move('back', " + dist + ");\n", "cf_move('back', " + dist + ")");
    };

    generatorObj.forBlock['cf_move_left'] = function () {
      var dist = getNumberField(this, 'DIST', 0.3);
      return emit("cf_move('left', " + dist + ");\n", "cf_move('left', " + dist + ")");
    };

    generatorObj.forBlock['cf_move_right'] = function () {
      var dist = getNumberField(this, 'DIST', 0.3);
      return emit("cf_move('right', " + dist + ");\n", "cf_move('right', " + dist + ")");
    };

    generatorObj.forBlock['cf_move_up'] = function () {
      var dist = getNumberField(this, 'DIST', 0.2);
      return emit("cf_move('up', " + dist + ");\n", "cf_move('up', " + dist + ")");
    };

    generatorObj.forBlock['cf_move_down'] = function () {
      var dist = getNumberField(this, 'DIST', 0.2);
      return emit("cf_move('down', " + dist + ");\n", "cf_move('down', " + dist + ")");
    };

    generatorObj.forBlock['cf_delay'] = function () {
      var secs = getNumberField(this, 'SECS', 1);
      return emit("cf_delay(" + secs + ");\n", "cf_delay(" + secs + ")");
    };
  }

  registerFor(window.Arduino, 'arduino');
  registerFor(window.MPY || window.MicropPython, 'python');
  registerFor((window.Blockly && window.Blockly.JavaScript) || null, 'javascript');
})();
